from collections import deque

def solve(grid, start, goal):
    queue = deque([start])
    explored = set([start])
    paths = {start: None}
    steps = {start}

    while queue:
        x, y = queue.popleft()

        if (x, y) == goal:
            path = []
            while (x, y) is not None:
                path.append((x, y))
                x, y = paths[(x, y)]
            return list(reversed(path))

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy

            if (0 <= nx < len(grid)) and (0 <= ny < len(grid[0])) and grid[nx][ny] == '.' and (nx, ny) not in explored:
                queue.append((nx, ny))
                explored.add((nx, ny))
                paths[(nx, ny)] = (x, y)
                steps.add((nx, ny))

    return []
