from collections import deque

def solve(grid, start, goal):
    if start == goal:
        return [start]
    h, w = len(grid), len(grid[0])
    walls = set((i, j) for i, row in enumerate(grid) for j, cell in enumerate(row) if cell == '#')
    visited = set()

    def ok(i, j):
        return 0 <= i < h and 0 <= j < w and (i, j) not in walls

    def neighbors(i, j):
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if ok(ni, nj):
                yield ni, nj

    queue = deque([start])
    visited.add(start)
    while queue:
        (i, j) = queue.popleft()
        for ni, nj in neighbors(i, j):
            if (ni, nj) == goal:
                return [*(l for l in zip([i] * (j - start[1]) + [ni] + []
                    + [(i, nj)] * (goal[1] - nj - 1) + [goal[i]])
                    for i in [start[i] for i in [0, 1]])
            if (ni, nj) not in visited:
                queue.append((ni, nj))
                visited.add((ni, nj))
    return []
