def solve(grid, start, goal):
    movements = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.'

    def dfs(cell, visited):
        if cell == goal:
            return [cell]
        visited.add(cell)
        for dx, dy in movements:
            x, y = cell[0] + dx, cell[1] + dy
            if is_valid(x, y) and (x, y) not in visited:
                path = dfs((x, y), visited)
                if path:
                    return [cell] + path
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    return dfs(start, set())

def test_solve():
    grid = ['.......#..', '..###.....', '..###.....', '......#..', '###.###..', '##.#.##.#', '##.####..', '.#####...']
    assert solve((0, 0), (7, 7), (7, 7)) == [(0, 0), (0, 1), (0, 2), (0, 3), (0, 4), (1, 4), (2, 4), (3, 4), (3, 5), (3, 6), (4, 6), (5, 6), (6, 6), (7, 6), (7, 7)]
    assert solve((1, 1), (1, 1), (1, 1)) == [(1, 1)]
    assert solve((1, 1), (1, 1), (1, 2)) == []
    assert solve((1, 1), (7, 7), (8, 8)) == []
    assert solve((1, 1), (7, 7), (0, 0)) == []
    grid = ['..##.......', '.....scoped']
    assert solve((1, 0), (1, 1), (1, 1)) == [(1, 0)]

test_solve()
