def solve(grid, start, goal):
    if start == goal:
        return [start]

    h, w = len(grid), len(grid[0])
    visited = [[False] * w for _ in range(h)]

    queue = deque([start])
    visited[start[0]][start[1]] = True

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        x, y = queue.popleft()

        if (x, y) == goal:
            path = [[x, y]]
            while path[-1] != start:
                for dx, dy in directions:
                    nx, ny = path[-1][0] + dx, path[-1][1] + dy
                    if 0 <= nx < h and 0 <= ny < w and not grid[nx][ny] == '#' and visited[nx][ny]:
                        path.append((nx, ny))
                        break
            return path[::-1]

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] != '#' and not visited[nx][ny]:
                queue.append((nx, ny))
                visited[nx][ny] = True

    return []
