from collections import deque

def solve(grid, start, goal):
    directions = [(0, -1), (0, 1), (-1, 0), (1, 0)]  # left, right, up, down
    rows, cols = len(grid), len(grid[0])

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] != '#'

    def adjacent(y):
        for dx, dy in directions:
            yield (y + dx, dy)

    if grid[start[0]][start[1]] == '#':
        return []

    if start == goal:
        return [start]

    queue = deque([start])
    visited = set([start])

    while queue:
        x, y = queue.popleft()
        if (x, y) == goal:
            path = [(x, y)]
            while path[-1] != start:
                for dx, dy in adjacent((x, y)):
                    if (dx, dy) in adjacent((path[-1][0], path[-1][1])):
                        break
                x, y = dx, dy
                path.append((x, y))
            return path[::-1]

        for dx, dy in adjacent((x, y)):
            if is_valid(dx, dy) and (dx, dy) not in visited:
                queue.append((dx, dy))
                visited.add((dx, dy))

    return []
