from collections import deque

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    visited = set()

    def valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] != '#'
    def enqueue(queue, node):
        yield node
        for dr, dc in directions:
            nr, nc = node[0] + dr, node[1] + dc
            if valid(nr, nc) and (nr, nc) not in visited:
                visited.add((nr, nc))
                yield from enqueue((nr, nc), queue)

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    queue = deque([start])
    while queue:
        node = queue.popleft()
        if node == goal:
            path = []
            while node:
                path.append(node)
                node = next((n for n in [s for s in enqueue(queue, node)] if n != start), None)
            return path[::-1]

        for n in enqueue(queue, node):
            yield from enqueue(queue, n)
    return []
